CREATE DATABASE IF NOT EXISTS jass CHARACTER SET utf8mb4;
USE jass;
CREATE TABLE IF NOT EXISTS usuarios(id INT AUTO_INCREMENT PRIMARY KEY,usuario VARCHAR(40) UNIQUE,clave VARCHAR(255),nombre VARCHAR(80));
CREATE TABLE IF NOT EXISTS socios(id INT AUTO_INCREMENT PRIMARY KEY,dni VARCHAR(12) UNIQUE,nombre VARCHAR(100),direccion VARCHAR(150),telefono VARCHAR(20),cod_conexion VARCHAR(20),estado ENUM('activo','cortado') DEFAULT 'activo');
CREATE TABLE IF NOT EXISTS lecturas(id INT AUTO_INCREMENT PRIMARY KEY,socio_id INT NOT NULL,periodo CHAR(7),anterior DECIMAL(10,2),actual DECIMAL(10,2),UNIQUE(socio_id,periodo),FOREIGN KEY(socio_id) REFERENCES socios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS recibos(id INT AUTO_INCREMENT PRIMARY KEY,socio_id INT NOT NULL,periodo CHAR(7),consumo DECIMAL(10,2),monto DECIMAL(10,2),estado ENUM('pendiente','pagado') DEFAULT 'pendiente',fecha_pago DATETIME NULL,UNIQUE(socio_id,periodo),FOREIGN KEY(socio_id) REFERENCES socios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS config(clave VARCHAR(30) PRIMARY KEY,valor DECIMAL(10,2));
INSERT IGNORE INTO config VALUES('cuota_fija',5.00),('m3_incluidos',10),('precio_m3',0.80);
ALTER TABLE usuarios ADD COLUMN IF NOT EXISTS rol ENUM('admin','cajero') NOT NULL DEFAULT 'cajero';
UPDATE usuarios SET rol='admin' WHERE usuario='admin';
ALTER TABLE recibos ADD COLUMN IF NOT EXISTS medio VARCHAR(20) NULL;
ALTER TABLE usuarios MODIFY rol ENUM('admin','presidente','tesorero','operador','cajero') NOT NULL DEFAULT 'operador';
CREATE TABLE IF NOT EXISTS tarifas(categoria VARCHAR(20) PRIMARY KEY,cuota_fija DECIMAL(10,2),m3_incluidos DECIMAL(10,2),precio_m3 DECIMAL(10,2));
INSERT IGNORE INTO tarifas VALUES('domestica',5,10,0.80),('comercial',10,10,1.20),('social',3,8,0.50);
CREATE TABLE IF NOT EXISTS medidores(id INT AUTO_INCREMENT PRIMARY KEY,socio_id INT NOT NULL,nro VARCHAR(20) UNIQUE,predio VARCHAR(150),categoria VARCHAR(20) DEFAULT 'domestica',estado ENUM('activo','cortado','malogrado') DEFAULT 'activo',FOREIGN KEY(socio_id) REFERENCES socios(id) ON DELETE CASCADE);
INSERT IGNORE INTO medidores(socio_id,nro,predio) SELECT id,CONCAT('M-',id),direccion FROM socios WHERE id NOT IN (SELECT socio_id FROM medidores);
ALTER TABLE lecturas ADD COLUMN IF NOT EXISTS incidencia VARCHAR(20) NOT NULL DEFAULT 'normal';
ALTER TABLE recibos ADD COLUMN IF NOT EXISTS extra DECIMAL(10,2) NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS cuotas(id INT AUTO_INCREMENT PRIMARY KEY,periodo CHAR(7),descripcion VARCHAR(100),monto DECIMAL(10,2));
CREATE TABLE IF NOT EXISTS egresos(id INT AUTO_INCREMENT PRIMARY KEY,fecha DATE,categoria VARCHAR(20),descripcion VARCHAR(150),monto DECIMAL(10,2));
CREATE TABLE IF NOT EXISTS cierres(fecha DATE PRIMARY KEY,esperado DECIMAL(10,2),contado DECIMAL(10,2),usuario VARCHAR(80));
CREATE TABLE IF NOT EXISTS calidad(id INT AUTO_INCREMENT PRIMARY KEY,fecha DATE,cloro DECIMAL(4,2),ph DECIMAL(3,1),turbidez DECIMAL(4,1),obs VARCHAR(150));
CREATE TABLE IF NOT EXISTS mantenimiento(id INT AUTO_INCREMENT PRIMARY KEY,fecha DATE,tipo VARCHAR(20),descripcion VARCHAR(150),responsable VARCHAR(60),estado ENUM('pendiente','atendido') DEFAULT 'pendiente');
